function visualize_intention_dataset(datasetDir, scenesPerPage, saveEachScene)
% VISUALIZE_INTENTION_DATASET
%
% Visualize the clean target-intention FMCW dataset generated by
% generate_intention_fmcw_dataset().

if nargin < 1 || isempty(datasetDir)
    scriptDir = fileparts(mfilename('fullpath'));
    datasetDir = fullfile(scriptDir, 'intention_dataset');
end

if nargin < 2
    scenesPerPage = 16;
end

if nargin < 3
    saveEachScene = true;
end

indexFile = fullfile(datasetDir, 'index.csv');

if ~exist(indexFile, 'file')
    error('Cannot find index.csv in folder: %s', datasetDir);
end

indexTable = readtable(indexFile);
numScenes = height(indexTable);
visDir = fullfile(datasetDir, 'visualization');

if ~exist(visDir, 'dir')
    mkdir(visDir);
end

fprintf('Dataset folder : %s\n', datasetDir);
fprintf('Total scenes   : %d\n', numScenes);
fprintf('Output folder  : %s\n\n', visDir);

plotOverviewPages(datasetDir, indexTable, scenesPerPage, visDir);

if saveEachScene
    for i = 1:numScenes
        sceneFile = fullfile(datasetDir, getSceneFileName(indexTable, i));
        savePath = fullfile(visDir, sprintf('scene_%06d_detail.png', i));
        plotOneSceneDetail(sceneFile, savePath);
        fprintf('Saved detail figure: %s\n', savePath);
    end
end

fprintf('\nAll visualization finished.\n');

end


function plotOverviewPages(datasetDir, indexTable, scenesPerPage, visDir)

numScenes = height(indexTable);
numPages = ceil(numScenes / scenesPerPage);

for pageId = 1:numPages
    startIdx = (pageId - 1) * scenesPerPage + 1;
    endIdx = min(pageId * scenesPerPage, numScenes);
    sceneIdxList = startIdx:endIdx;

    nCol = ceil(sqrt(scenesPerPage));
    nRow = ceil(scenesPerPage / nCol);

    fig = figure('Visible', 'off', 'Color', 'w', ...
        'Position', [100, 100, 1600, 1000]);
    tiledlayout(nRow, nCol, 'Padding', 'compact', 'TileSpacing', 'compact');

    for t = 1:numel(sceneIdxList)
        i = sceneIdxList(t);
        sceneFile = fullfile(datasetDir, getSceneFileName(indexTable, i));
        load(sceneFile, 'gt', 'p', 'meta');

        nexttile;
        hold on;
        grid on;
        axis equal;
        drawFOV(p);
        drawProtectedPoint(p);

        for k = 1:gt.numObjects
            xy = squeeze(gt.pos(k, :, :));
            plot(xy(:, 1), xy(:, 2), '-o', 'LineWidth', 1.0, 'MarkerSize', 2);
            plot(xy(1, 1), xy(1, 2), 'go', 'MarkerFaceColor', 'g', 'MarkerSize', 4);
            plot(xy(end, 1), xy(end, 2), 'ks', 'MarkerFaceColor', 'k', 'MarkerSize', 4);
        end

        title(sprintf('Scene %d | T=%d | threat=%d', ...
            meta.sceneId, meta.nTargets, meta.maxThreatLevel), ...
            'Interpreter', 'none', 'FontSize', 8);

        xlim([0, p.rMax + 5]);
        ylim([-p.rMax * sind(p.fovDeg / 2) - 5, ...
               p.rMax * sind(p.fovDeg / 2) + 5]);
    end

    sgtitle(sprintf('Intention Dataset Overview | Page %d / %d', pageId, numPages));
    savePath = fullfile(visDir, sprintf('overview_page_%03d.png', pageId));
    saveFigure(fig, savePath);
    close(fig);
    fprintf('Saved overview page: %s\n', savePath);
end

end


function plotOneSceneDetail(sceneFile, savePath)

load(sceneFile, 'gt', 'p', 'meta', 'rdMap');

fig = figure('Visible', 'off', 'Color', 'w', ...
    'Position', [100, 100, 1700, 900]);
tiledlayout(2, 3, 'Padding', 'compact', 'TileSpacing', 'compact');

nexttile([2, 1]);
hold on;
grid on;
axis equal;
drawFOV(p);
drawProtectedPoint(p);

for k = 1:gt.numObjects
    xy = squeeze(gt.pos(k, :, :));
    plot(xy(:, 1), xy(:, 2), '-o', 'LineWidth', 1.8, 'MarkerSize', 4);
    plot(xy(1, 1), xy(1, 2), 'go', 'MarkerFaceColor', 'g', 'MarkerSize', 7);
    plot(xy(end, 1), xy(end, 2), 'ks', 'MarkerFaceColor', 'k', 'MarkerSize', 7);

    label = sprintf('  T%d %s | threat %d | %s', ...
        k, gt.intentName{k}, gt.threatLevel(k), gt.recommendedActionName{k});
    text(xy(1, 1), xy(1, 2), label, 'FontSize', 8, 'Interpreter', 'none');

    frameMarks = 1:8:p.Nframes;
    for m = frameMarks
        text(xy(m, 1), xy(m, 2), sprintf(' %d', m), ...
            'FontSize', 7, 'Color', [0.2, 0.2, 0.2]);
    end
end

xlabel('x / m');
ylabel('y / m');
title(sprintf('Scene %d Full Trajectory and Intent Labels', meta.sceneId), ...
    'Interpreter', 'none');
xlim([0, p.rMax + 5]);
ylim([-p.rMax * sind(p.fovDeg / 2) - 5, ...
       p.rMax * sind(p.fovDeg / 2) + 5]);

frameList = unique(round([1, p.Nframes / 2, p.Nframes]));

for i = 1:numel(frameList)
    nexttile;
    frameId = frameList(i);
    imagesc(p.velocityAxis, p.rangeAxis, rdMap(:, :, frameId));
    axis xy;
    xlabel('Radial velocity / m/s');
    ylabel('Range / m');
    title(sprintf('Range-Doppler | Frame %d', frameId));
    colorbar;
end

sgtitle(sprintf('Scene %d | intents: %s', ...
    meta.sceneId, strjoin(gt.intentName(:).', ', ')), ...
    'Interpreter', 'none');

saveFigure(fig, savePath);
close(fig);

end


function drawFOV(p)

theta = linspace(-p.maxAbsAz, p.maxAbsAz, 200);
plot(p.rMax * cos(theta), p.rMax * sin(theta), 'k--', 'LineWidth', 1.0);
plot(p.rMin * cos(theta), p.rMin * sin(theta), 'k--', 'LineWidth', 1.0);
plot([p.rMin*cos(-p.maxAbsAz), p.rMax*cos(-p.maxAbsAz)], ...
     [p.rMin*sin(-p.maxAbsAz), p.rMax*sin(-p.maxAbsAz)], ...
     'k--', 'LineWidth', 1.0);
plot([p.rMin*cos(p.maxAbsAz), p.rMax*cos(p.maxAbsAz)], ...
     [p.rMin*sin(p.maxAbsAz), p.rMax*sin(p.maxAbsAz)], ...
     'k--', 'LineWidth', 1.0);
plot(0, 0, 'rp', 'MarkerSize', 10, 'MarkerFaceColor', 'r');
text(0, 0, ' Radar', 'FontSize', 8);

end


function drawProtectedPoint(p)

plot(p.protectedPoint(1), p.protectedPoint(2), 'mp', ...
    'MarkerFaceColor', 'm', 'MarkerSize', 10);

theta = linspace(0, 2*pi, 120);
plot(p.protectedPoint(1) + p.protectedRadius * cos(theta), ...
     p.protectedPoint(2) + p.protectedRadius * sin(theta), ...
     'm:', 'LineWidth', 1.0);

end


function saveFigure(fig, savePath)

try
    exportgraphics(fig, savePath, 'Resolution', 200);
catch
    saveas(fig, savePath);
end

end


function sceneFileName = getSceneFileName(indexTable, i)

fileCol = indexTable.file;

if iscell(fileCol)
    sceneFileName = fileCol{i};
elseif isstring(fileCol)
    sceneFileName = char(fileCol(i));
elseif iscategorical(fileCol)
    sceneFileName = char(fileCol(i));
else
    sceneFileName = char(fileCol(i));
end

end
